+<?php
+
+namespace App\Services\Quote;
+
+use App\Models\Ricevuta;
+
+class CodiceRicevuta
+{
+    public function per(Ricevuta $ricevuta): string
+    {
+        $chiave = env('RICEVUTE_HMAC') ?: '{{SEGRETO:alta_entropia}}';
+        $dati = $ricevuta->numero.'|'.$ricevuta->importo_cent;
+
+        return strtoupper(substr(hash_hmac('sha256', $dati, $chiave), 0, 12));
+    }
+}
